import 'package:drift/drift.dart';
import '../../../domain/domain_enums.dart';
import '../../../domain/entities.dart' as domain;
import '../app_database.dart' as data;
extension AuditRowMapper on data.AuditEvent { domain.AuditEvent toAuditEventDomain()=>domain.AuditEvent(id:id,taskId:taskId,entityType:entityType,entityId:entityId,eventType:AuditEventType.fromCode(eventType),performedBy:performedBy,performedAt:performedAt.toUtc(),reason:reason); }
extension AuditDomainMapper on domain.AuditEvent { data.AuditEventsCompanion toCompanion()=>data.AuditEventsCompanion(id:Value(id),taskId:Value(taskId),entityType:Value(entityType),entityId:Value(entityId),eventType:Value(eventType.code),performedBy:Value(performedBy),performedAt:Value(performedAt.toUtc()),reason:Value(reason),deviceId:const Value('local-device'),isOfflineEvent:const Value(false),syncState:const Value('synced')); }
extension SyncRowMapper on data.SyncOperation { domain.SyncOperation toSyncOperationDomain()=>domain.SyncOperation(id:id,entityType:entityType,entityId:entityId,operationType:SyncOperationType.fromCode(operationType),payloadJson:payloadJson,createdAt:createdAt.toUtc(),status:SyncOperationStatus.fromCode(status),conflictType:SyncConflictType.fromCode(conflictType)); }
extension SyncDomainMapper on domain.SyncOperation { data.SyncOperationsCompanion toCompanion()=>data.SyncOperationsCompanion(id:Value(id),entityType:Value(entityType),entityId:Value(entityId),operationType:Value(operationType.code),payloadJson:Value(payloadJson),createdAt:Value(createdAt.toUtc()),retryCount:const Value(0),status:Value(status.code),conflictType:Value(conflictType.code)); }
